#pragma once

// Raw Unicode data generated by tools/generate_unicode_tables.py. Every table
// is sorted by code point so lookups can binary-search it. Use the functions
// in model/unicode.hpp rather than these tables directly.

#include <cstdint>
#include <span>

namespace murmur::unicode::tables {

struct CodepointRange {
    char32_t first;
    char32_t last;   // inclusive
};

struct CombiningClassRange {
    char32_t first;
    char32_t last;   // inclusive
    std::uint8_t combining_class;
};

// One level of canonical decomposition: DecompositionData()[offset, offset + length).
struct Decomposition {
    char32_t codepoint;
    std::uint16_t offset;
    std::uint8_t length;
};

// Sorted by (first, second).
struct Composition {
    char32_t first;
    char32_t second;
    char32_t composite;
};

std::span<const CodepointRange> LetterRanges();
std::span<const CodepointRange> NumberRanges();
std::span<const CodepointRange> WhiteSpaceRanges();
std::span<const CombiningClassRange> CombiningClassRanges();
std::span<const Decomposition> Decompositions();
std::span<const char32_t> DecompositionData();
std::span<const Composition> Compositions();

}  // namespace murmur::unicode::tables
